      SUBROUTINE FINGERCC     FILL IN POINTERS FOR BEAM LINE SPECIFICATIONSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BROAD.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA1D.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8F.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM24A.CIN'      INCLUDE 'ELM26A.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'ELM38B.CIN'      INCLUDE 'INDPAR.CIN'CC     LOCAL VARIABLESC      CHARACTER*15    LABLE      EXTERNAL        IDATACC---------------------------------------------------------------------CC     PROCESS DATAC      NUM = 1      IOLD = 0      ALIGN = .FALSE.      NUP(1) = 0      NUP(2) = 0      NUP(3) = 0      NC = 0      NV1 = 0      BAX = .FALSE.      RANZC = .FALSE.      NMARKB = 0      NMARKE = 0      NMISRB = 0      NMISRE = 0      NB22 = 0      NBPLOT = 0      BROAD = .FALSE.C   70 I = ISTOR(NUM)      TYPE = IDATA(I)      LABLE = LABEL(NUM)      IF (NUSE .EQ. 0 .AND. I .LE. IOLD) GO TO 6100      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 6100      CALL SKETCH(NUM)CC     PROCESS ORIGINAL DATAC      IF (TYPE .EQ. 6) GO TO 600      IF (TYPE .EQ. 8) GO TO 800      IF (TYPE .EQ. 10) GO TO 1000      IF (TYPE .EQ. 13) GO TO 1300      IF (TYPE .EQ. 22) GO TO 2200      IF (TYPE .EQ. 24) GO TO 2400      IF (TYPE .EQ. 26) GO TO 2600      IF (TYPE .EQ. 33) GO TO 3300      IF (TYPE .EQ. 37) GO TO 3700      IF (TYPE .EQ. 38) GO TO 3800      IF (TYPE .EQ. 40) GO TO 4000      IF (TYPE .EQ. 44) GO TO 4400      GO TO 6000CC     UPDATEC  600 IF (IPTOJ(3) .NE. 0) THEN        IF (NMARKB .EQ. 0) NMARKB = NUM        NMARKE = NUM      ENDIF      GO TO 6000CC     MISALIGNMENTC  800 ALIGN = .TRUE.      TYT = INT(DATA(I+7))      LFM = TYT/100      IF (LFM .GE. 2) RANZC = .TRUE.      RORC = MOD(TYT,10)      IR = RORC + 1      IF (LFM .GE. 1 .AND. RORC .LE. 2) NUP(IR) = NUP(IR) + 1      IF (IDATA(I+9) .NE. 0) THEN         IF (TIE(I+9) .EQ. 102) THEN          IF (NMISRB .EQ. 0) THEN            NMISRB = NUM          ENDIF          NMISRE = NUM        ELSE IF (TIE(I+9) .EQ. 101) THEN          IF (NMARKB .EQ. 0) NMARKB = NUM          NMARKE = NUM        ENDIF      ENDIF      GO TO 6000CC     CONSTRAINTC 1000 NC = NC + 1      ILOC = 7      IF (IPTOJ(ILOC) .NE. 0) THEN        IF (NMARKB .EQ. 0) THEN          IF (NB22 .EQ. 0) THEN            NMARKB = NUM          ELSE            NMARKB = NB22          ENDIF        ENDIF        NMARKE = NUM      ENDIF      NB22 = 0      GO TO 6000CC     INPUT/OUTPUT OPTIONC 1300 CDB = INT(DATA(I+1))      IF (CDB .EQ. 9) BAX = .TRUE.      IF (IPTOJ(2) .NE. 0) THEN        IF (NMARKB .EQ. 0) NMARKB = NUM        NMARKE = NUM      ENDIF      GO TO 6000CC     MATRIX ELEMENTC 2200 IF (NB22 .EQ. 0) NB22 = NUM      GO TO 6000CC     DEFINED SECTIONC 2400 JDEF = IDATA(I+1)      IF (JDEF .EQ. 1 .OR. JDEF .EQ. 2) CALL FNDREF(LABLE)      GO TO 6100CC     RANDOM ERRORS IN PHYSICAL PARAMETERSC 2600 RANZC = .TRUE.      GO TO 6000CC     STOREC 3300 IF (IPTOJ(2) .NE. 0) THEN        IF (NMARKB .EQ. 0) THEN          IF (NB22 .EQ. 0) THEN            NMARKB = NUM          ELSE            NMARKB = NB22          ENDIF        ENDIF        NMARKE = NUM      ENDIF      NB22 = 0      GO TO 6000CC     ALIGNMENT MARKERC 3700 IF (IPTOJ(3) .NE. 0) THEN        IF (NMARKB .EQ. 0) NMARKB = NUM        NMARKE = NUM      ENDIF      GO TO 6000CC     PLOT OF MATRIX ELEMENTC 3800 IF (NBPLOT .EQ. 0) THEN        IF (NB22 .NE. 0) NBPLOT = NB22        IF (NB22 .EQ. 0) NBPLOT = NUM      ENDIF      GO TO 6000CC     MAGNET TYPESC 4000 CALL FNDMAG(LBTYP(NUM))      GO TO 6000CC     BROAD-BAND FITTINGC 4400 BROAD = .TRUE.      GO TO 6000CC     CHECK VARY CODESC 6000 IBEG = I + 1      NUM1 = NUM 6001 IEND = ISTOR(NUM1 + 1)      IF (IEND .LT. IBEG) THEN        NUM1 = NUM1 + 1        GO TO 6001      ENDIF 6005 IEND = IEND - 1      DO 6010 IB = IBEG, IEND      NV2 = IABS(TIE(IB))      IF (NV2 .LT. 99) NV1 = MAX0(NV1,NV2) 6010 CONTINUECC     ADVANCE TO NEXT ELEMENTC 6100 IOLD = MAX0(I,IOLD)      NUM = NUM + 1      IF (NUM .LE. NEL) GO TO 70      RETURN      END